import json,sys
from pathlib import Path
from hashlib import sha256
from collections import defaultdict
sys.path.insert(0,str(Path.cwd()))
from src.workstation.recording import RecordingReader
from src.workstation.projection import adapter_for_stream
from src.workstation.events import Trade
from src.workstation import wire
ROOT=Path('data/m5-profile/queue-service')
results=[]
for name in ('original','direct-queue','bounded-inline'):
 for result in json.loads((ROOT/(name+'.json')).read_text()):
  with RecordingReader(result['capture'],verify=False,allow_incomplete=True) as reader:
   specs={s.stream_id:s for s in reader.manifest.streams};adapters={k:adapter_for_stream(s) for k,s in specs.items()}
   expected=defaultdict(list);actual=defaultdict(list);seen=defaultdict(set)
   for f in reader.iter_raw():
    s=specs[f.stream_id]
    if s.key.channel!='trades':continue
    for event in adapters[f.stream_id].decode(f,s.instrument,s.key).events:
     p=event.payload
     if isinstance(p,Trade) and p.dedup_key not in seen[f.stream_id]:
      seen[f.stream_id].add(p.dedup_key);expected[f.stream_id].append(p)
   for batch in reader.iter_batches():
    for event in batch.events:
     if isinstance(event.payload,Trade):actual[event.stream_id].append(event.payload)
   depths=[]
   for record in reader.iter_checkpoints():
    book=record.checkpoint.book
    if book is not None:depths.append({'stream_id':record.checkpoint.stream_id,'bid_levels':len(book.bids),'ask_levels':len(book.asks),'integrity':book.quality.integrity})
   def digest(values):return sha256(wire.dumps(tuple((k,tuple(v)) for k,v in sorted(values.items())),canonical=True)).hexdigest()
   results.append({'case':result['label'],'native_payloads_exact_per_stream':dict(expected)==dict(actual),'expected_trade_counts':{k:len(v) for k,v in expected.items()},'actual_trade_counts':{k:len(v) for k,v in actual.items()},'expected_native_wire_sha256':digest(expected),'actual_native_wire_sha256':digest(actual),'checkpoint_depths':depths})
(ROOT/'native-parity.json').write_text(json.dumps(results,indent=2)+'\n')
print(json.dumps(results),flush=True)
